cd "$ARCHON_HORIZON_ROOT"; "$HORIZON_GIT" status --porcelain -- MainProjects/Algebraic-Jacobian-Challenge 2>&1 | grep -v hgraph/nodes; echo "=== unrooted lean modules ==="; cd MainProjects/Algebraic-Jacobian-Challenge; python3 - <<'EOF'
import re,os,subprocess
root=open('AlgebraicJacobian.lean').read()
imported=set(re.findall(r'^import (\S+)',root,re.M))
allmods=set()
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f)
            allmods.add(p[:-5].replace('/','.'))
# transitive closure
def imports_of(m):
    p=m.replace('.','/')+'.lean'
    if not os.path.exists(p): return []
    return re.findall(r'^import (\S+)',open(p).read(),re.M)
seen=set()
stack=list(imported)
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for i in imports_of(m):
        if i.startswith('AlgebraicJacobian'): stack.append(i)
unreached=sorted(allmods-seen)
print(len(allmods),'modules,',len(allmods&seen),'reachable')
for u in unreached: print('  UNROOTED',u)
EOF
